namespace App\Filament\Exports;

use App\Models\Booking;
use Filament\Actions\Exports\ExportColumn;
use Filament\Actions\Exports\Exporter;
use Filament\Actions\Exports\Models\Export;
use Illuminate\Support\Number;

/**
 * Generated exporter for Bookings records (CSV/XLSX).
 */
class BookingExporter extends Exporter
{
    protected static ?string $model = Booking::class;

    /**
     * Columns included in the export.
     * @return  array  Export column definitions.
     */
    public static function getColumns(): array
    {
        return [
                        ExportColumn::make('id')->limit(50)->label('Id'),
            ExportColumn::make('created_at')->limit(50)->label('Created At'),
            ExportColumn::make('updated_at')->limit(50)->label('Updated At'),
            ExportColumn::make('deleted_at')->limit(50)->label('Deleted At'),
            ExportColumn::make('created_by')->limit(50)->label('Created By'),
            ExportColumn::make('updated_by')->limit(50)->label('Updated By'),
            ExportColumn::make('deleted_by')->limit(50)->label('Deleted By'),
            ExportColumn::make('booking_ref')->limit(50)->label('Booking Ref'),
            ExportColumn::make('bookableResource.id')->limit(50)->label('Resource'),
            ExportColumn::make('booker_name')->limit(50)->label('Booker Name'),
            ExportColumn::make('booker_email')->limit(50)->label('Booker Email'),
            ExportColumn::make('start_datetime')->limit(50)->label('Start'),
            ExportColumn::make('end_datetime')->limit(50)->label('End'),
            ExportColumn::make('attendees')->limit(50)->label('Attendees'),
            ExportColumn::make('notes')->limit(50)->label('Notes'),
            ExportColumn::make('booking_status')->limit(50)->label('Status'),
        ];
    }

    /**
     * Notification body shown when the export finishes.
     *
     * @param  Export  $export  The completed export job.
     * @return  string  Human-readable completion summary.
     */
    public static function getCompletedNotificationBody(Export $export): string
    {
        $body = 'Your Bookings export has completed and ' . Number::format($export->successful_rows) . ' ' . str('row')->plural($export->successful_rows) . ' exported.';

        if ($failedRowsCount = $export->getFailedRowsCount()) {
            $body .= ' ' . Number::format($failedRowsCount) . ' ' . str('row')->plural($failedRowsCount) . ' failed to export.';
        }

        return $body;
    }
}
